  'Carcinoma en cuirasse' => 'A form of advanced breast cancer in which tumor spreads through skin lymphatics, producing diffuse hardening, thickening, and retraction of the chest wall skin.',
  'Carcinoma in Situ' => 'A neoplastic epithelial lesion with malignant cellular features confined above the basement membrane, without invasion into surrounding tissue, though it may progress to invasive cancer.'
}

text = File.read(FILE)
changed = 0
DEFINITIONS.each do |term, definition|
  escaped = Regexp.escape(term)
  pattern = /^\\medterm\{#{escaped}\} .*?(?=^\\medterm\{|\z)/m
  text = text.gsub(pattern) do |block|
    next block unless block.match?(/is a medical or biological concept|is an anatomical or physiologic term|is an anatomical or histologic term|is a biological, genetic|is a disease, symptom|is a diagnostic or laboratory|describes a clinical disorder|is a healthcare or clinical-care term/)
    changed += 1
    "\\medterm{#{term}} #{definition}\n\n"
  end
end
File.write(FILE, text)
puts "#{FILE}: replaced=#{changed}"
